mons=[x**i*v**j for i in range(3) for j in range(3-i)]
def run(w,harm):
    C=np.cos(w*t);S=np.sin(w*t)
    cols=[m for m in mons]+[m*C for m in mons]+[m*S for m in mons]
    for h in harm:
        cols+= [np.cos(h*w*t),np.sin(h*w*t)]
    X=np.column_stack(cols); c=np.linalg.lstsq(X,dv_dt,rcond=None)[0]; r=dv_dt-X@c
    return np.mean(r**2)/np.var(dv_dt), c
for harm in [[2],[3],[0.5]]:
    best=(9,)
    for w in np.linspace(0.05,0.6,1101):
        q,c=run(w,harm)
        if q<best[0]: best=(q,w)
    print(harm,best)
